def add_memory(workspace_id, actor_id, content, source=None, metadata=None, importance=None, expires_at=None, **_extra):
    import json, os, datetime, re, hashlib, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0126000" if __import__("os").path.isdir("./environment_mix/0126000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _normalize_content(c):
        # Deterministic normalization for dedupe:
        # trim, collapse whitespace, lowercase
        c = c.strip()
        c = re.sub(r"\s+", " ", c)
        c = c.lower()
        return c

    def _new_id(prefix, rows):
        # prefix like "mem_mem_" with base36-ish uppercase; ensure uniqueness in file
        import random, string
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = string.digits + string.ascii_uppercase
        for _ in range(2000):
            suffix = "".join(random.choice(alphabet) for _ in range(12))
            _id = f"{prefix}{suffix}"
            if _id not in existing:
                return _id
        # fallback: timestamp-based
        suffix = str(int(time.time() * 1000))
        return f"{prefix}{suffix}"

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^mem_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")
    if not isinstance(actor_id, str) or not re.match(r"^mem_act_[0-9A-Z]+$", actor_id):
        return _err("VALIDATION_ERROR", "Invalid actor_id format.", field="actor_id")
    if not isinstance(content, str) or len(content) < 1 or len(content) > 20000:
        return _err("VALIDATION_ERROR", "Invalid content length; must be 1..20000.", field="content")
    if source is None:
        source = "tool:add-memory"
    if not isinstance(source, str) or source not in ("tool:add-memory", "import", "system"):
        return _err("VALIDATION_ERROR", "Invalid source.", field="source")
    if metadata is None:
        metadata = {}
    if not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object.", field="metadata")
    if importance is None:
        importance = 0.5
    if not isinstance(importance, (int, float)) or importance < 0 or importance > 1:
        return _err("VALIDATION_ERROR", "importance must be a number between 0 and 1.", field="importance")

    exp_dt = None
    if expires_at is not None:
        exp_dt = _parse_rfc3339(expires_at)
        if exp_dt is None:
            return _err("VALIDATION_ERROR", "expires_at must be a valid RFC 3339 date-time.", field="expires_at")

    # Load state
    workspaces = _load("workspaces.json")
    actors = _load("actors.json")
    memories = _load("memories.json")
    mem_index = _load("memory_index.json")

    # Resolve workspace + actor and enforce lifecycle/FK rules
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") != "active":
        return _err("INVALID_TRANSITION", "Workspace is not active.", workspace_id=workspace_id, status=ws.get("status"))

    act = next((a for a in actors if isinstance(a, dict) and a.get("id") == actor_id), None)
    if not act:
        return _err("NOT_FOUND", "Actor not found.", actor_id=actor_id)
    if act.get("status") != "active":
        return _err("INVALID_TRANSITION", "Actor is not active.", actor_id=actor_id, status=act.get("status"))
    if act.get("workspace_id") != workspace_id:
        return _err("VALIDATION_ERROR", "Actor does not belong to the provided workspace.", field="actor_id", actor_workspace_id=act.get("workspace_id"))

    # Quota: maximum 100,000 active memories per workspace
    active_count = 0
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") == workspace_id and m.get("status") == "active":
            # also treat expired-by-time as not active (auto-expire) for quota accuracy
            mexp = _parse_rfc3339(m.get("expires_at")) if m.get("expires_at") else None
            if mexp is not None and mexp <= now:
                continue
            active_count += 1
    if active_count >= 100000:
        return _err("QUOTA_EXCEEDED", "Workspace active memory quota exceeded.", limit=100000, workspace_id=workspace_id)

    # Auto-expire any memories that should be expired (active -> expired)
    # This keeps search semantics consistent across calls.
    changed = False
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") != workspace_id:
            continue
        if m.get("status") == "active" and m.get("expires_at"):
            mexp = _parse_rfc3339(m.get("expires_at"))
            if mexp is not None and mexp <= now:
                m["status"] = "expired"
                m["updated_at"] = _iso(now)
                changed = True
    if changed:
        _save("memories.json", memories)

    # Dedup / idempotency by (workspace_id, actor_id, content_hash) where status != deleted
    norm = _normalize_content(content)
    chash = hashlib.sha256(norm.encode("utf-8")).hexdigest()

    existing = None
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") == workspace_id and m.get("actor_id") == actor_id and m.get("content_hash") == chash and m.get("status") != "deleted":
            # If it's expired already, it's still "non-deleted"; spec says do not create duplicate.
            existing = m
            break

    # Always upsert index row to pending/stale to trigger reindexing, even when idempotent hit.
    def _upsert_index(memory_row, prefer_status=None):
        nonlocal mem_index
        mem_id = memory_row.get("id")
        if not mem_id:
            return
        idx = next((r for r in mem_index if isinstance(r, dict) and r.get("memory_id") == mem_id), None)
        target_status = prefer_status or "pending"
        if idx is None:
            idx = {
                "id": _new_id("mem_midx_", mem_index),
                "memory_id": mem_id,
                "workspace_id": memory_row.get("workspace_id"),
                "actor_id": memory_row.get("actor_id"),
                "index_version": 1,
                "embedding_model": None,
                "embedding": None,
                "tsv": None,
                "status": target_status,
                "last_indexed_at": None,
                "error_message": None,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            mem_index.append(idx)
        else:
            # transitions: ready->stale allowed; stale->pending allowed; failed->pending allowed; pending unchanged
            cur = idx.get("status")
            allowed = {
                "pending": {"ready", "failed"},
                "ready": {"stale"},
                "stale": {"pending", "ready", "failed"},
                "failed": {"pending"},
            }
            if cur != target_status:
                if cur in allowed and target_status in allowed[cur]:
                    idx["status"] = target_status
                else:
                    # If cannot transition directly to pending, move via stale if possible
                    if cur == "ready" and target_status == "pending":
                        idx["status"] = "stale"
                    elif cur == "pending" and target_status == "stale":
                        # not allowed by schema; keep pending
                        pass
                    else:
                        # keep current to avoid illegal transition
                        pass
            idx["workspace_id"] = memory_row.get("workspace_id")
            idx["actor_id"] = memory_row.get("actor_id")
            if not isinstance(idx.get("index_version"), int) or idx["index_version"] < 1:
                idx["index_version"] = 1
            idx["updated_at"] = _iso(now)
            if idx.get("status") != "failed":
                idx["error_message"] = None
        _save("memory_index.json", mem_index)

    if existing is not None:
        # Ensure expires_at constraint: stored expires_at must be >= created_at; already true in DB; ignore request expires_at.
        _upsert_index(existing, prefer_status="pending")
        latency = int((time.perf_counter() - t0) * 1000)
        return {
            "memory": existing,
            "accepted_for_indexing": True,
            "idempotent": True,
            "latency_ms": latency,
        }

    # Create new memory row
    created_at = now
    if exp_dt is not None and exp_dt < created_at:
        return _err("VALIDATION_ERROR", "expires_at must be null or >= created_at.", field="expires_at")

    mem_id = _new_id("mem_mem_", memories)
    mem_row = {
        "id": mem_id,
        "workspace_id": workspace_id,
        "actor_id": actor_id,
        "source": "tool:add-memory",  # business rule
        "content": content,
        "content_hash": chash,
        "metadata": metadata,
        "importance": float(importance),
        "expires_at": _iso(exp_dt) if exp_dt is not None else None,
        "status": "active",
        "created_at": _iso(created_at),
        "updated_at": _iso(created_at),
        "deleted_at": None,
    }

    # Enforce unique(workspace_id, actor_id, content_hash) where status != 'deleted'
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") == workspace_id and m.get("actor_id") == actor_id and m.get("content_hash") == chash and m.get("status") != "deleted":
            # race-like condition in file DB; idempotently return existing
            _upsert_index(m, prefer_status="pending")
            latency = int((time.perf_counter() - t0) * 1000)
            return {
                "memory": m,
                "accepted_for_indexing": True,
                "idempotent": True,
                "latency_ms": latency,
            }

    memories.append(mem_row)
    _save("memories.json", memories)

    # Upsert memory_index as pending to trigger indexing
    _upsert_index(mem_row, prefer_status="pending")

    latency = int((time.perf_counter() - t0) * 1000)
    return {
        "memory": mem_row,
        "accepted_for_indexing": True,
        "idempotent": False,
        "latency_ms": latency,
    }

def search_memories(workspace_id, actor_id, query_text, top_k=None, filter=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0126000" if __import__("os").path.isdir("./environment_mix/0126000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.perf_counter()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix, rows):
        import random, string
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        alphabet = string.digits + string.ascii_uppercase
        for _ in range(2000):
            suffix = "".join(random.choice(alphabet) for _ in range(12))
            _id = f"{prefix}{suffix}"
            if _id not in existing:
                return _id
        suffix = str(int(time.time() * 1000))
        return f"{prefix}{suffix}"

    def _log_search(search_requests, ws_id, act_id, qtext, tk, flt, status, results_count, latency_ms, error_message=None):
        row = {
            "id": _new_id("mem_sreq_", search_requests),
            "workspace_id": ws_id,
            "actor_id": act_id,
            "query_text": qtext,
            "top_k": tk,
            "filter": flt if isinstance(flt, dict) else {},
            "results_count": int(results_count),
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "status": status,
            "error_message": error_message,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        search_requests.append(row)
        _save("search_requests.json", search_requests)

    # Validate inputs (but still log call if possible; if formats invalid we cannot trust tenant scoping, so do not log)
    if not isinstance(workspace_id, str) or not re.match(r"^mem_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id format.", field="workspace_id")
    if not isinstance(actor_id, str) or not re.match(r"^mem_act_[0-9A-Z]+$", actor_id):
        return _err("VALIDATION_ERROR", "Invalid actor_id format.", field="actor_id")
    if not isinstance(query_text, str) or len(query_text.strip()) < 1:
        return _err("VALIDATION_ERROR", "query_text must be a non-empty string.", field="query_text")
    if top_k is None:
        top_k = 10
    if not isinstance(top_k, int) or top_k < 1 or top_k > 100:
        return _err("VALIDATION_ERROR", "top_k must be an integer between 1 and 100.", field="top_k")
    if filter is None:
        filter = {}
    if not isinstance(filter, dict):
        return _err("VALIDATION_ERROR", "filter must be an object.", field="filter")

    # Load state
    workspaces = _load("workspaces.json")
    actors = _load("actors.json")
    memories = _load("memories.json")
    search_requests = _load("search_requests.json")

    # Resolve workspace + actor
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    act = next((a for a in actors if isinstance(a, dict) and a.get("id") == actor_id), None)

    # Rate limit: max 60 searches per minute per actor (based on search_requests)
    # Enforce before executing, but after validating actor_id format.
    # If actor doesn't exist, still return NOT_FOUND (and do not rate-limit).
    if act is not None:
        window_start = now - datetime.timedelta(minutes=1)
        cnt = 0
        for r in search_requests:
            if not isinstance(r, dict):
                continue
            if r.get("actor_id") != actor_id:
                continue
            ts = _parse_rfc3339(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start:
                cnt += 1
        if cnt >= 60:
            latency = int((time.perf_counter() - t0) * 1000)
            _log_search(search_requests, workspace_id, actor_id, query_text, top_k, filter, "error", 0, latency, error_message="Rate limit exceeded: 60 searches per minute per actor.")
            return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=60, actor_id=actor_id)

    # Now enforce prerequisites and log accordingly
    if ws is None:
        latency = int((time.perf_counter() - t0) * 1000)
        # cannot log without valid FK; but workspace_id is syntactically valid; still, FK would fail. Do not log.
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if act is None:
        latency = int((time.perf_counter() - t0) * 1000)
        return _err("NOT_FOUND", "Actor not found.", actor_id=actor_id)
    if act.get("workspace_id") != workspace_id:
        latency = int((time.perf_counter() - t0) * 1000)
        _log_search(search_requests, workspace_id, actor_id, query_text, top_k, filter, "error", 0, latency, error_message="Actor does not belong to workspace.")
        return _err("VALIDATION_ERROR", "Actor does not belong to the provided workspace.", field="actor_id", actor_workspace_id=act.get("workspace_id"))

    if ws.get("status") != "active":
        latency = int((time.perf_counter() - t0) * 1000)
        _log_search(search_requests, workspace_id, actor_id, query_text, top_k, filter, "error", 0, latency, error_message="Workspace is not active.")
        return _err("INVALID_TRANSITION", "Workspace is not active.", workspace_id=workspace_id, status=ws.get("status"))
    if act.get("status") != "active":
        latency = int((time.perf_counter() - t0) * 1000)
        _log_search(search_requests, workspace_id, actor_id, query_text, top_k, filter, "error", 0, latency, error_message="Actor is not active.")
        return _err("INVALID_TRANSITION", "Actor is not active.", actor_id=actor_id, status=act.get("status"))

    # Auto-expire memories where expires_at <= now (active -> expired)
    mem_changed = False
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") != workspace_id:
            continue
        if m.get("status") == "active" and m.get("expires_at"):
            exp = _parse_rfc3339(m.get("expires_at"))
            if exp is not None and exp <= now:
                m["status"] = "expired"
                m["updated_at"] = _iso(now)
                mem_changed = True
    if mem_changed:
        _save("memories.json", memories)

    # Apply required filters: active and not expired by time; also only within workspace + actor scope
    q = query_text.strip().lower()
    q_terms = [t for t in re.split(r"\s+", q) if t]

    # Optional structured filters (best-effort; always recorded regardless of support)
    # Supported keys: "tags" (list of strings), "created_after", "created_before"
    tags = None
    created_after = None
    created_before = None
    if "tags" in filter:
        if not isinstance(filter["tags"], list) or any(not isinstance(x, str) for x in filter["tags"]):
            latency = int((time.perf_counter() - t0) * 1000)
            _log_search(search_requests, workspace_id, actor_id, query_text, top_k, filter, "error", 0, latency, error_message="Invalid filter.tags; must be list of strings.")
            return _err("VALIDATION_ERROR", "filter.tags must be a list of strings.", field="filter.tags")
        tags = [t.strip().lower() for t in filter["tags"] if t.strip()]
    if "created_after" in filter:
        if not isinstance(filter["created_after"], str) or _parse_rfc3339(filter["created_after"]) is None:
            latency = int((time.perf_counter() - t0) * 1000)
            _log_search(search_requests, workspace_id, actor_id, query_text, top_k, filter, "error", 0, latency, error_message="Invalid filter.created_after; must be RFC3339.")
            return _err("VALIDATION_ERROR", "filter.created_after must be an RFC 3339 date-time string.", field="filter.created_after")
        created_after = _parse_rfc3339(filter["created_after"])
    if "created_before" in filter:
        if not isinstance(filter["created_before"], str) or _parse_rfc3339(filter["created_before"]) is None:
            latency = int((time.perf_counter() - t0) * 1000)
            _log_search(search_requests, workspace_id, actor_id, query_text, top_k, filter, "error", 0, latency, error_message="Invalid filter.created_before; must be RFC3339.")
            return _err("VALIDATION_ERROR", "filter.created_before must be an RFC 3339 date-time string.", field="filter.created_before")
        created_before = _parse_rfc3339(filter["created_before"])

    def _score(m):
        # Simple offline scoring: term hits in content, plus importance weight
        content = (m.get("content") or "").lower()
        hits = 0
        for t in q_terms:
            if t in content:
                hits += 1
        imp = m.get("importance")
        try:
            imp = float(imp)
        except Exception:
            imp = 0.5
        return hits * 10.0 + imp

    candidates = []
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") != workspace_id:
            continue
        if m.get("actor_id") != actor_id:
            continue
        if m.get("status") != "active":
            continue
        exp = _parse_rfc3339(m.get("expires_at")) if m.get("expires_at") else None
        if exp is not None and exp <= now:
            continue

        if created_after is not None or created_before is not None:
            mc = _parse_rfc3339(m.get("created_at"))
            if mc is not None:
                if created_after is not None and mc < created_after:
                    continue
                if created_before is not None and mc > created_before:
                    continue

        if tags is not None:
            md = m.get("metadata")
            md_tags = []
            if isinstance(md, dict) and isinstance(md.get("tags"), list):
                md_tags = [str(x).strip().lower() for x in md.get("tags") if str(x).strip()]
            # require all tags
            if any(t not in md_tags for t in tags):
                continue

        # query match: require at least one term
        content = (m.get("content") or "").lower()
        if q_terms and not any(t in content for t in q_terms):
            continue

        candidates.append(m)

    # Rank by score desc, then updated_at desc
    def _dt_or_min(s):
        d = _parse_rfc3339(s) if isinstance(s, str) else None
        return d or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    candidates.sort(key=lambda m: (_score(m), _dt_or_min(m.get("updated_at"))), reverse=True)
    results = candidates[:top_k]

    latency = int((time.perf_counter() - t0) * 1000)
    _log_search(search_requests, workspace_id, actor_id, query_text, top_k, filter, "ok", len(results), latency, error_message=None)

    return {
        "memories": results,
        "top_k": top_k,
        "returned": len(results),
        "latency_ms": latency,
    }

def list_memories(workspace_id, actor_id, status=None, include_expired=None, include_deleted=None, created_after=None, created_before=None, expires_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0126000" if __import__("os").path.isdir("./environment_mix/0126000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _to_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _parse_rfc3339(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 date-time string")
        dt = _to_dt(s)
        if dt is None:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a valid RFC3339 date-time string")
        return dt, None

    def _iso(dt):
        if dt is None:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _b64url_encode(b):
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _b64url_decode(s):
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        return base64.urlsafe_b64decode((s + pad).encode("ascii"))

    def _make_cursor(created_at_iso, mem_id):
        payload = {"v": 1, "created_at": created_at_iso, "id": mem_id}
        return _b64url_encode(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8"))

    def _parse_cursor(cur):
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string")
        try:
            obj = json.loads(_b64url_decode(cur.strip()).decode("utf-8"))
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")
        if not isinstance(obj, dict) or obj.get("v") != 1:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")
        ca = obj.get("created_at")
        mid = obj.get("id")
        if not isinstance(ca, str) or not isinstance(mid, str):
            return None, _err("VALIDATION_ERROR", "cursor is invalid")
        dt = _to_dt(ca)
        if dt is None:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")
        return {"created_at": dt, "created_at_iso": _iso(dt), "id": mid}, None

    # ---- Validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^mem_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must match ^mem_ws_[0-9A-Z]+$", workspace_id=workspace_id)
    if not isinstance(actor_id, str) or not re.match(r"^mem_act_[0-9A-Z]+$", actor_id):
        return _err("VALIDATION_ERROR", "actor_id must match ^mem_act_[0-9A-Z]+$", actor_id=actor_id)

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "expired", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, expired, deleted", status=status)

    if include_expired is not None and not isinstance(include_expired, bool):
        return _err("VALIDATION_ERROR", "include_expired must be a boolean", include_expired=include_expired)
    if include_deleted is not None and not isinstance(include_deleted, bool):
        return _err("VALIDATION_ERROR", "include_deleted must be a boolean", include_deleted=include_deleted)

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", limit=limit)

    ca_dt, e = _parse_rfc3339(created_after, "created_after")
    if e:
        return e
    cb_dt, e = _parse_rfc3339(created_before, "created_before")
    if e:
        return e
    eb_dt, e = _parse_rfc3339(expires_before, "expires_before")
    if e:
        return e

    cur, e = _parse_cursor(cursor)
    if e:
        return e

    # ---- Load refs / access checks (ambient auth: accept if store has an accessible combo) ----
    workspaces = _load("workspaces.json")
    actors = _load("actors.json")
    memories = _load("memories.json")
    search_requests = _load("search_requests.json")

    ws = next((r for r in workspaces if isinstance(r, dict) and r.get("id") == workspace_id), None)
    act = next((r for r in actors if isinstance(r, dict) and r.get("id") == actor_id), None)

    # log helper (must log every call)
    def _log(ws_id, act_id, top_k, filt, status_s, err_msg=None, results_count=0):
        now = _now_utc()
        now_iso = _iso(now)
        # generate id
        existing = set(r.get("id") for r in search_requests if isinstance(r, dict))
        base = int(now.timestamp() * 1000)
        srq_id = None
        for i in range(10000):
            cand = f"mem_srq_{(base + i):X}"
            if cand not in existing:
                srq_id = cand
                break
        if srq_id is None:
            srq_id = f"mem_srq_{base:X}F"
        row = {
            "id": srq_id,
            "workspace_id": ws_id,
            "actor_id": act_id,
            "query_text": None,
            "top_k": int(top_k),
            "filter": filt if isinstance(filt, dict) else {},
            "results_count": int(results_count),
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "status": status_s,
            "error_message": err_msg,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        search_requests.append(row)
        _save("search_requests.json", search_requests)

    # Reject invalid references / FK mismatch
    if ws is None:
        _log(workspace_id, actor_id, limit, {"op": "list-memories"}, "error", "Workspace not found", results_count=0)
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if act is None:
        _log(workspace_id, actor_id, limit, {"op": "list-memories"}, "error", "Actor not found", results_count=0)
        return _err("NOT_FOUND", "Actor not found.", actor_id=actor_id)
    if act.get("workspace_id") != workspace_id:
        _log(workspace_id, actor_id, limit, {"op": "list-memories"}, "error", "Actor does not belong to workspace", results_count=0)
        return _err("VALIDATION_ERROR", "FK mismatch: actor.workspace_id must match workspace_id.", actor_id=actor_id, workspace_id=workspace_id)

    # Accessibility: treat non-active as not accessible to caller per tool description.
    if ws.get("status") != "active" or act.get("status") != "active":
        _log(workspace_id, actor_id, limit, {"op": "list-memories"}, "error", "Workspace/actor not accessible", results_count=0)
        return _err("UNAUTHORIZED", "Workspace/actor not accessible (must be active).", workspace_status=ws.get("status"), actor_status=act.get("status"))

    # Rate limit: 60 search_requests per minute per actor
    now = _now_utc()
    one_min_ago = now - datetime.timedelta(minutes=1)
    recent = 0
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("actor_id") != actor_id:
            continue
        dt = _to_dt(r.get("created_at"))
        if dt is not None and dt > one_min_ago:
            recent += 1
    if recent >= 60:
        _log(workspace_id, actor_id, limit, {"op": "list-memories"}, "error", "Rate limited: too many search requests (60/min) for actor", results_count=0)
        return _err("RATE_LIMIT", "Rate limited: too many search requests (60/min) for actor", actor_id=actor_id)

    # ---- Auto-expire memories where expires_at <= now (business rule) ----
    changed = False
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") != workspace_id or m.get("actor_id") != actor_id:
            continue
        if m.get("status") != "active":
            continue
        exp = _to_dt(m.get("expires_at"))
        if exp is not None and exp <= now:
            # active -> expired is allowed
            m["status"] = "expired"
            m["updated_at"] = _iso(now)
            changed = True
    if changed:
        _save("memories.json", memories)

    # ---- Filter and paginate ----
    def _created_dt(m):
        dt = _to_dt(m.get("created_at"))
        return dt if dt is not None else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    filtered = []
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") != workspace_id or m.get("actor_id") != actor_id:
            continue

        m_status = m.get("status")
        if m_status not in ("active", "expired", "deleted"):
            continue

        # status/include flags logic
        if status is not None:
            if m_status != status:
                continue
        else:
            if m_status == "deleted":
                if not include_deleted:
                    continue
            elif m_status == "expired":
                if not include_expired:
                    continue
            else:
                # active always included
                pass

        cdt = _created_dt(m)
        if ca_dt is not None and not (cdt > ca_dt):
            continue
        if cb_dt is not None and not (cdt < cb_dt):
            continue

        if eb_dt is not None:
            expdt = _to_dt(m.get("expires_at"))
            if expdt is None or not (expdt < eb_dt):
                continue

        filtered.append(m)

    # Order by created_at desc, tie-breaker by id desc
    filtered.sort(key=lambda r: (_created_dt(r), str(r.get("id") or "")), reverse=True)

    # Apply cursor (created_at,id) pagination; cursor means "start after this item"
    if cur is not None:
        new_filtered = []
        for m in filtered:
            mcdt = _created_dt(m)
            mid = str(m.get("id") or "")
            # If m is strictly "after" cursor in desc order, skip until we pass it; we want items with (created_at,id) < cursor in desc ordering
            if mcdt < cur["created_at"] or (mcdt == cur["created_at"] and mid < cur["id"]):
                new_filtered.append(m)
        filtered = new_filtered

    page = filtered[:limit]
    has_more = len(filtered) > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _make_cursor(_iso(_created_dt(last)), str(last.get("id") or ""))

    _log(
        workspace_id,
        actor_id,
        limit,
        {
            "op": "list-memories",
            "status": status,
            "include_expired": bool(include_expired) if include_expired is not None else False,
            "include_deleted": bool(include_deleted) if include_deleted is not None else False,
            "created_after": created_after,
            "created_before": created_before,
            "expires_before": expires_before,
        },
        "ok",
        None,
        results_count=len(page),
    )

    return {
        "object": "list",
        "data": page,
        "workspace_id": workspace_id,
        "actor_id": actor_id,
        "total": len(filtered),
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_memory(workspace_id, memory_id, include_deleted=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0126000" if __import__("os").path.isdir("./environment_mix/0126000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.now(datetime.timezone.utc)
    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _log_search_request(workspace_id_val, actor_id_val, top_k_val, filt_obj, results_count_val, status_val, error_message_val, latency_ms_val):
        sr = _load("search_requests.json")
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        def _new_id(prefix):
            import random
            ts = int(_now().timestamp() * 1000)
            rnd = "".join(random.choice(alphabet) for _ in range(10))
            return f"{prefix}{ts:X}{rnd}"
        rid = _new_id("mem_sreq_")
        ts = _now().isoformat()
        row = {
            "id": rid,
            "workspace_id": workspace_id_val,
            "actor_id": actor_id_val,
            "query_text": None,
            "top_k": int(top_k_val),
            "filter": filt_obj if isinstance(filt_obj, dict) else {},
            "results_count": int(results_count_val),
            "latency_ms": int(latency_ms_val) if latency_ms_val is not None else None,
            "status": status_val,
            "error_message": error_message_val if status_val == "error" else None,
            "created_at": ts,
            "updated_at": ts,
        }
        sr.append(row)
        _save("search_requests.json", sr)

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^mem_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id is invalid")
    if not isinstance(memory_id, str) or not re.match(r"^mem_mem_[0-9A-Z]+$", memory_id):
        return _err("VALIDATION_ERROR", "memory_id is invalid")
    if include_deleted is not None and not isinstance(include_deleted, bool):
        return _err("VALIDATION_ERROR", "include_deleted must be boolean")

    # Load collections
    workspaces = _load("workspaces.json")
    actors = _load("actors.json")
    memories = _load("memories.json")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        # We don't know actor_id for the request log; attempt to use the memory's actor if it exists, else a placeholder actor is impossible.
        latency_ms = max(0, int(((_now() - t0).total_seconds()) * 1000))
        # Try infer actor_id via memory if present in store
        mem_row = next((m for m in memories if isinstance(m, dict) and m.get("id") == memory_id), None)
        inferred_actor = mem_row.get("actor_id") if isinstance(mem_row, dict) else "mem_act_UNKNOWN"
        _log_search_request(workspace_id, inferred_actor, 10, {"op": "get-memory"}, 0, "error", "workspace not found", latency_ms)
        return _err("NOT_FOUND", "workspace not found")

    # Must be accessible
    if ws.get("status") != "active":
        latency_ms = max(0, int(((_now() - t0).total_seconds()) * 1000))
        mem_row = next((m for m in memories if isinstance(m, dict) and m.get("id") == memory_id), None)
        inferred_actor = mem_row.get("actor_id") if isinstance(mem_row, dict) else "mem_act_UNKNOWN"
        _log_search_request(workspace_id, inferred_actor, 10, {"op": "get-memory"}, 0, "error", "workspace not accessible", latency_ms)
        return _err("UNAUTHORIZED", "workspace not accessible")

    mem = next((m for m in memories if isinstance(m, dict) and m.get("id") == memory_id and m.get("workspace_id") == workspace_id), None)
    if mem is None:
        latency_ms = max(0, int(((_now() - t0).total_seconds()) * 1000))
        _log_search_request(workspace_id, "mem_act_UNKNOWN", 10, {"op": "get-memory"}, 0, "error", "memory not found", latency_ms)
        return _err("NOT_FOUND", "memory not found")

    # Enforce FK integrity: actor must exist and belong to workspace
    act = next((a for a in actors if isinstance(a, dict) and a.get("id") == mem.get("actor_id")), None)
    if act is None or act.get("workspace_id") != workspace_id:
        latency_ms = max(0, int(((_now() - t0).total_seconds()) * 1000))
        _log_search_request(workspace_id, mem.get("actor_id") or "mem_act_UNKNOWN", 10, {"op": "get-memory"}, 0, "error", "FK mismatch", latency_ms)
        return _err("VALIDATION_ERROR", "memory actor FK is invalid for this workspace")

    # Actor accessibility for read
    if act.get("status") != "active":
        latency_ms = max(0, int(((_now() - t0).total_seconds()) * 1000))
        _log_search_request(workspace_id, act.get("id"), 10, {"op": "get-memory"}, 0, "error", "actor not accessible", latency_ms)
        return _err("UNAUTHORIZED", "actor not accessible")

    # If deleted and not allowed, return NOT_FOUND
    if mem.get("status") == "deleted" and not bool(include_deleted):
        latency_ms = max(0, int(((_now() - t0).total_seconds()) * 1000))
        _log_search_request(workspace_id, act.get("id"), 10, {"op": "get-memory", "include_deleted": include_deleted}, 0, "error", "memory not found", latency_ms)
        return _err("NOT_FOUND", "memory not found")

    latency_ms = max(0, int(((_now() - t0).total_seconds()) * 1000))
    _log_search_request(workspace_id, act.get("id"), 10, {"op": "get-memory", "include_deleted": include_deleted}, 1, "ok", None, latency_ms)

    return {"object": "memory", "data": mem}

def update_memory(workspace_id, memory_id, content=None, metadata=None, importance=None, expires_at=None, status=None, **_extra):
    import json, os, datetime, hashlib, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0126000" if __import__("os").path.isdir("./environment_mix/0126000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(val, field_name):
        if val is None:
            return None, None
        if not isinstance(val, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an RFC3339 datetime string or null")
        s = val.strip()
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a valid RFC3339 datetime string")
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc), None

    def _normalize_content(c):
        return " ".join(c.strip().split())

    def _hash_content(norm):
        return hashlib.sha256(norm.encode("utf-8")).hexdigest()

    def _coerce_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _wrap_like(original, rows):
        if isinstance(original, dict) and "rows" in original:
            out = dict(original)
            out["rows"] = rows
            return out
        return rows

    def _gen_id(prefix, existing_ids):
        # vendor-like monotonic hex millis; ensure uniqueness
        ts = int(_utcnow().timestamp() * 1000)
        for i in range(10000):
            cand = f"{prefix}{(ts + i):X}"
            if cand not in existing_ids:
                return cand
        return f"{prefix}{ts:X}F"

    # ---- validate inputs (schema) ----
    if not isinstance(workspace_id, str) or not re.match(r"^mem_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "workspace_id must be a string matching ^mem_ws_[0-9A-Z]+$")
    if not isinstance(memory_id, str) or not re.match(r"^mem_mem_[0-9A-Z]+$", memory_id):
        return _err("VALIDATION_ERROR", "memory_id must be a string matching ^mem_mem_[0-9A-Z]+$")

    if content is not None:
        if not isinstance(content, str) or len(content) < 1:
            return _err("VALIDATION_ERROR", "content must be a non-empty string")
        if len(content) > 20000:
            return _err("VALIDATION_ERROR", "content length must be <= 20000")

    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object")

    if importance is not None:
        if not isinstance(importance, (int, float)) or isinstance(importance, bool):
            return _err("VALIDATION_ERROR", "importance must be a number between 0 and 1")
        if importance < 0 or importance > 1:
            return _err("VALIDATION_ERROR", "importance must be between 0 and 1")

    expires_dt, eerr = _parse_rfc3339(expires_at, "expires_at")
    if eerr:
        return eerr

    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "expired"):
            return _err("VALIDATION_ERROR", "status must be one of: active, expired")

    # ---- load stores ----
    workspaces_raw = _load("workspaces.json")
    actors_raw = _load("actors.json")
    memories_raw = _load("memories.json")
    index_raw = _load("memory_index.json")

    workspaces = _coerce_rows(workspaces_raw)
    actors = _coerce_rows(actors_raw)
    memories = _coerce_rows(memories_raw)
    mindex = _coerce_rows(index_raw)

    # ---- resolve referenced rows ----
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    # Updates are internal admin-like; only forbid deleted workspace
    if ws.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot update memory in a deleted workspace.", workspace_id=workspace_id)

    mem = next((m for m in memories if isinstance(m, dict) and m.get("id") == memory_id), None)
    if mem is None:
        return _err("NOT_FOUND", "Memory not found.", memory_id=memory_id)

    # The request's workspace_id must match the memory's workspace_id (FK integrity).
    # If it doesn't, this is a real conflict (caller targeting wrong tenant).
    mem_ws_id = mem.get("workspace_id")
    if mem_ws_id != workspace_id:
        return _err(
            "CONFLICT",
            "FK integrity violation: memory.workspace_id must match the provided workspace_id.",
            rule="memories.workspace_id must equal tool workspace_id",
            memory_id=memory_id,
            workspace_id=workspace_id,
            memory_workspace_id=mem_ws_id
        )

    # FK: actor exists and belongs to same workspace
    actor_id = mem.get("actor_id")
    act = next((a for a in actors if isinstance(a, dict) and a.get("id") == actor_id), None)
    if act is None:
        return _err("CONFLICT", "FK integrity violation: memory.actor_id does not reference an existing actor.", rule="foreign key (actor_id) references actors(id)", actor_id=actor_id)
    if act.get("workspace_id") != workspace_id:
        return _err(
            "CONFLICT",
            "FK integrity violation: actor.workspace_id must match memory.workspace_id.",
            rule="memories.workspace_id must match actors.workspace_id",
            memory_id=memory_id,
            memory_workspace_id=workspace_id,
            actor_id=actor_id,
            actor_workspace_id=act.get("workspace_id")
        )

    # ---- automatic expiry transition on read/update ----
    now = _utcnow()
    existing_expires = mem.get("expires_at")
    existing_expires_dt = None
    if isinstance(existing_expires, str):
        existing_expires_dt, _ = _parse_rfc3339(existing_expires, "expires_at")

    if mem.get("status") == "active" and existing_expires_dt is not None and existing_expires_dt <= now:
        mem["status"] = "expired"
        mem["updated_at"] = _iso(now)

    # ---- forbid updates to deleted memories ----
    if mem.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Cannot modify a deleted memory.", memory_id=memory_id)

    # ---- apply lifecycle transition if requested ----
    if status is not None and status != mem.get("status"):
        cur = mem.get("status")
        allowed = {"active": {"expired"}, "expired": set(), "deleted": set()}
        if cur not in allowed or status not in allowed[cur]:
            return _err(
                "INVALID_TRANSITION",
                "Illegal memory status transition.",
                from_status=cur,
                to_status=status,
                allowed=list(sorted(allowed.get(cur, set())))
            )
        mem["status"] = status
        mem["updated_at"] = _iso(now)

    # ---- validate/compute new expires_at (must be >= created_at when set) ----
    if expires_at is not None:
        # expires_at may be explicit null (None) to clear, or RFC3339 string
        if expires_dt is None:
            mem["expires_at"] = None
        else:
            created_at_dt, cerr = _parse_rfc3339(mem.get("created_at"), "created_at")
            if cerr:
                # corrupted row; surface as error instead of masking
                return _err("CONFLICT", "Stored memory has invalid created_at timestamp.", memory_id=memory_id)
            if created_at_dt is not None and expires_dt < created_at_dt:
                return _err(
                    "VALIDATION_ERROR",
                    "Business rule violation: expires_at must be null or >= created_at.",
                    rule="expires_at is null or expires_at >= created_at",
                    created_at=mem.get("created_at"),
                    expires_at=_iso(expires_dt)
                )
            mem["expires_at"] = _iso(expires_dt)
        mem["updated_at"] = _iso(now)

    # ---- apply field updates ----
    content_changed = False
    new_hash = None
    if content is not None:
        norm = _normalize_content(content)
        new_hash = _hash_content(norm)
        if new_hash != mem.get("content_hash") or content != mem.get("content"):
            content_changed = True
        mem["content"] = content
        mem["content_hash"] = new_hash
        mem["updated_at"] = _iso(now)

    if metadata is not None:
        mem["metadata"] = metadata
        mem["updated_at"] = _iso(now)

    if importance is not None:
        mem["importance"] = float(importance)
        mem["updated_at"] = _iso(now)

    # ---- enforce uniqueness (workspace_id, actor_id, content_hash) where status != 'deleted' ----
    if content_changed:
        # Note: if caller changed content to match another existing non-deleted memory, reject.
        for m in memories:
            if not isinstance(m, dict):
                continue
            if m.get("id") == memory_id:
                continue
            if m.get("workspace_id") == workspace_id and m.get("actor_id") == actor_id and m.get("status") != "deleted" and m.get("content_hash") == new_hash:
                return _err(
                    "CONFLICT",
                    "Business rule violation: duplicate memory content for this actor in this workspace.",
                    rule="unique(workspace_id, actor_id, content_hash) where status != 'deleted'",
                    existing_memory_id=m.get("id"),
                    memory_id=memory_id
                )

    # ---- quota: max 100,000 active memories per workspace ----
    # Only relevant if update causes memory to be active (or stays active) and memory wasn't already active.
    # We'll compute active count excluding this row, then add if resulting status is active.
    resulting_status = mem.get("status")
    active_without_this = 0
    for m in memories:
        if not isinstance(m, dict):
            continue
        if m.get("workspace_id") != workspace_id:
            continue
        if m.get("id") == memory_id:
            continue
        if m.get("status") == "active":
            # exclude already-expired-by-time (auto expire for counting too)
            ex = m.get("expires_at")
            exdt = None
            if isinstance(ex, str):
                exdt, _ = _parse_rfc3339(ex, "expires_at")
            if exdt is not None and exdt <= now:
                continue
            active_without_this += 1

    will_be_active = (resulting_status == "active")
    # if active but expires_at <= now, it would be auto-expired; treat as not active
    mem_exdt = None
    if isinstance(mem.get("expires_at"), str):
        mem_exdt, _ = _parse_rfc3339(mem.get("expires_at"), "expires_at")
    if will_be_active and mem_exdt is not None and mem_exdt <= now:
        will_be_active = False
        # auto-expire it to keep invariant
        mem["status"] = "expired"
        mem["updated_at"] = _iso(now)
        resulting_status = "expired"

    if will_be_active and (active_without_this + 1) > 100000:
        return _err(
            "QUOTA_EXCEEDED",
            "Workspace memory quota exceeded: maximum 100000 active memories per workspace.",
            rule="maximum 100,000 active memories per workspace",
            workspace_id=workspace_id,
            limit=100000
        )

    # ---- schedule reindex if content changed ----
    if content_changed:
        # Upsert memory_index unique(memory_id)
        idx = next((r for r in mindex if isinstance(r, dict) and r.get("memory_id") == memory_id), None)
        now_iso = _iso(now)
        if idx is None:
            existing_ids = {r.get("id") for r in mindex if isinstance(r, dict) and isinstance(r.get("id"), str)}
            idx_id = _gen_id("mem_idx_", existing_ids)
            idx = {
                "id": idx_id,
                "memory_id": memory_id,
                "workspace_id": workspace_id,
                "actor_id": actor_id,
                "index_version": 1,
                "embedding_model": None,
                "embedding": None,
                "tsv": None,
                "status": "pending",
                "last_indexed_at": None,
                "error_message": None,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            mindex.append(idx)
        else:
            # If ready -> stale; else pending is fine; failed -> pending.
            cur_s = idx.get("status")
            if cur_s == "ready":
                idx["status"] = "stale"
            else:
                idx["status"] = "pending"
            idx["workspace_id"] = workspace_id
            idx["actor_id"] = actor_id
            if not isinstance(idx.get("index_version"), int) or idx.get("index_version", 0) < 1:
                idx["index_version"] = 1
            idx["error_message"] = None if idx.get("status") != "failed" else idx.get("error_message")
            idx["updated_at"] = now_iso

    # ---- persist ----
    _save("memories.json", _wrap_like(memories_raw, memories))
    if content_changed:
        _save("memory_index.json", _wrap_like(index_raw, mindex))

    latency_ms = int((time.time() - t0) * 1000)

    # return updated memory (as stored) + indexing hint
    out = dict(mem)
    out_meta = {
        "latency_ms": latency_ms,
        "reindexed": bool(content_changed),
        "memory_index_status": None
    }
    if content_changed:
        idx2 = next((r for r in mindex if isinstance(r, dict) and r.get("memory_id") == memory_id), None)
        if isinstance(idx2, dict):
            out_meta["memory_index_status"] = idx2.get("status")

    return {"memory": out, "meta": out_meta}

def delete_memory(workspace_id, memory_id, reason=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0126000" if __import__("os").path.isdir("./environment_mix/0126000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    def _iso(dt):
        if dt is None: return None
        if dt.tzinfo is None: dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    if not isinstance(workspace_id, str) or not re.match(r"^mem_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(memory_id, str) or not re.match(r"^mem_mem_[0-9A-Z]+$", memory_id):
        return _err("VALIDATION_ERROR", "Invalid memory_id.")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "Invalid reason; must be a string.")

    workspaces = _load("workspaces.json")
    memories = _load("memories.json")
    memory_index = _load("memory_index.json")

    ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws_row:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    mem = next((m for m in memories if isinstance(m, dict) and m.get("id") == memory_id), None)
    if not mem:
        return _err("NOT_FOUND", "Memory not found.")
    if mem.get("workspace_id") != workspace_id:
        return _err("CONFLICT", "Memory does not belong to the specified workspace.")
    if mem.get("status") == "deleted":
        return _err("INVALID_TRANSITION", "Memory is already deleted.")

    # Transition to deleted
    mem["status"] = "deleted"
    mem["deleted_at"] = _iso(now)
    mem["updated_at"] = _iso(now)
    if reason:
        md = mem.get("metadata")
        if not isinstance(md, dict):
            md = {}
        md.setdefault("deletion", {})
        if not isinstance(md.get("deletion"), dict):
            md["deletion"] = {}
        md["deletion"]["reason"] = reason
        md["deletion"]["deleted_at"] = _iso(now)
        mem["metadata"] = md

    # Cascade/invalidate memory_index: on delete cascade, remove row(s) for memory_id
    before_len = len(memory_index)
    memory_index = [r for r in memory_index if not (isinstance(r, dict) and r.get("memory_id") == memory_id)]
    # If nothing removed and you want to keep for audit, mark stale; but cascade is allowed by schema.
    # We'll treat cascade deletion as primary.
    _save("memories.json", memories)
    _save("memory_index.json", memory_index)

    return {
        "memory": mem,
        "memory_index_deleted": (before_len != len(memory_index)),
        "deleted_at": mem.get("deleted_at"),
    }

def list_search_requests(workspace_id, actor_id, status=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0126000" if __import__("os").path.isdir("./environment_mix/0126000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    def _parse_rfc3339(s):
        if s is None: return None
        if not isinstance(s, str):
            raise ValueError("bad ts")
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        dt = datetime.datetime.fromisoformat(ss)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    if not isinstance(workspace_id, str) or not re.match(r"^mem_ws_[0-9A-Z]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(actor_id, str) or not re.match(r"^mem_act_[0-9A-Z]+$", actor_id):
        return _err("VALIDATION_ERROR", "Invalid actor_id.")
    if status is not None and (not isinstance(status, str) or status not in ("ok", "error")):
        return _err("VALIDATION_ERROR", "Invalid status filter; must be 'ok' or 'error'.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be 1..200.")
    try:
        ca = _parse_rfc3339(created_after) if created_after is not None else None
    except Exception:
        return _err("VALIDATION_ERROR", "Invalid created_after; must be RFC3339 date-time.")
    try:
        cb = _parse_rfc3339(created_before) if created_before is not None else None
    except Exception:
        return _err("VALIDATION_ERROR", "Invalid created_before; must be RFC3339 date-time.")

    # Decode cursor
    cursor_created_at = None
    cursor_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or len(cursor) > 5000:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            cursor_created_at = _parse_rfc3339(obj.get("created_at")) if obj.get("created_at") else None
            cursor_id = obj.get("id")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    workspaces = _load("workspaces.json")
    actors = _load("actors.json")
    search_requests = _load("search_requests.json")

    ws_row = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if not ws_row:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws_row.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    act = next((a for a in actors if isinstance(a, dict) and a.get("id") == actor_id), None)
    if not act:
        return _err("NOT_FOUND", "Actor not found.")
    if act.get("workspace_id") != workspace_id:
        return _err("CONFLICT", "Actor does not belong to the specified workspace.")
    if act.get("status") != "active":
        return _err("UNAUTHORIZED", "Actor is not active.")

    # Filter
    filtered = []
    for r in search_requests:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id or r.get("actor_id") != actor_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        try:
            r_created = _parse_rfc3339(r.get("created_at")) if r.get("created_at") else None
        except Exception:
            r_created = None
        if ca is not None and (r_created is None or r_created <= ca):
            continue
        if cb is not None and (r_created is None or r_created >= cb):
            continue
        filtered.append((r_created, r.get("id"), r))

    # Order by created_at desc then id desc
    filtered.sort(key=lambda t: (t[0] or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), t[1] or ""), reverse=True)

    # Apply cursor (exclusive)
    if cursor_created_at is not None or cursor_id is not None:
        out2 = []
        for (rc, rid, rr) in filtered:
            # Keep items strictly "after" cursor in the sort order (desc):
            # skip until we pass cursor (i.e., items with (created_at, id) <= cursor tuple are after it in list)
            if rc is None:
                # poorly formed row; keep deterministic: treat as very old, will come later; apply cursor by id only
                pass
            if cursor_created_at is None:
                # only id cursor
                if rid is not None and cursor_id is not None and rid >= cursor_id:
                    continue
            else:
                tup = (rc or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), rid or "")
                cur_tup = (cursor_created_at, cursor_id or "")
                if tup >= cur_tup:
                    # in desc ordering, >= means same/newer -> already seen
                    continue
            out2.append((rc, rid, rr))
        filtered = out2

    total = len(filtered)
    page = [rr for (_, __, rr) in filtered[:limit]]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        enc = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    return {
        "data": page,
        "workspace_id": workspace_id,
        "actor_id": actor_id,
        "meta": {
            "limit": limit,
            "returned": len(page),
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

def get_auth_context(workspace_id=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0126000" if __import__("os").path.isdir("./environment_mix/0126000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)

    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^mem_ws_[0-9A-Z]+$", workspace_id):
            return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    workspaces = _load("workspaces.json")
    actors = _load("actors.json")
    memories = _load("memories.json")
    search_requests = _load("search_requests.json")

    # This service schema exposes no credential collection, and this tool requires credentials.
    # Therefore, unless the datastore includes some explicit credential material, this endpoint cannot authenticate.
    # Try to find any "service" actor marked as active to represent the caller; if none, refuse.
    caller_actor = None
    for a in actors:
        if isinstance(a, dict) and a.get("status") == "active" and a.get("type") in ("service", "agent", "user"):
            caller_actor = a
            break
    if caller_actor is None:
        return _err("UNAUTHORIZED", "Missing/invalid credentials (no authenticated principal available in datastore).")

    # Authorized workspaces: actor's workspace only (no ACLs are modeled)
    authorized_ws_ids = {caller_actor.get("workspace_id")} if caller_actor.get("workspace_id") else set()
    if workspace_id is not None and workspace_id not in authorized_ws_ids:
        return _err("UNAUTHORIZED", "Not authorized for the requested workspace.")

    # Workspace summaries
    ws_rows = [w for w in workspaces if isinstance(w, dict) and w.get("id") in authorized_ws_ids]
    if workspace_id is not None:
        ws_rows = [w for w in ws_rows if w.get("id") == workspace_id]
    if not ws_rows:
        return _err("NOT_FOUND", "Workspace not found or not authorized.")

    # compute active memories usage and per-actor search rate consumption (60/min per actor)
    one_min_ago = now - datetime.timedelta(minutes=1)

    def _parse_rfc3339(s):
        if s is None or not isinstance(s, str):
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except Exception:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _is_expired_row(mrow):
        if mrow.get("expires_at") in (None, ""):
            return False
        dt = _parse_rfc3339(mrow.get("expires_at"))
        return dt is not None and dt <= now

    ws_infos = []
    for w in ws_rows:
        wid = w.get("id")
        active_mem = 0
        for m in memories:
            if not isinstance(m, dict): 
                continue
            if m.get("workspace_id") != wid:
                continue
            if m.get("status") != "active":
                continue
            if _is_expired_row(m):
                continue
            active_mem += 1

        # rate limit state for caller actor only (since tool is about calling identity)
        actor_search_1m = 0
        for r in search_requests:
            if not isinstance(r, dict):
                continue
            if r.get("workspace_id") != wid:
                continue
            if r.get("actor_id") != caller_actor.get("id"):
                continue
            dt = _parse_rfc3339(r.get("created_at"))
            if dt is not None and dt >= one_min_ago:
                actor_search_1m += 1

        ws_infos.append({
            "workspace": {"id": wid, "name": w.get("name"), "status": w.get("status")},
            "quota": {
                "active_memories": {"limit": 100000, "used": active_mem, "remaining": max(0, 100000 - active_mem)}
            },
            "rate_limits": {
                "search_requests_per_minute": {
                    "limit": 60,
                    "used": actor_search_1m,
                    "remaining": max(0, 60 - actor_search_1m),
                    "window_seconds": 60
                }
            }
        })

    return {
        "caller": {
            "actor_id": caller_actor.get("id"),
            "type": caller_actor.get("type"),
            "workspace_id": caller_actor.get("workspace_id"),
            "external_ref": caller_actor.get("external_ref"),
            "display_name": caller_actor.get("display_name"),
        },
        "authorized_workspaces": [w.get("id") for w in ws_rows],
        "scopes": ["memories:read", "memories:write", "search:read"],  # best-effort; not modeled in schema
        "context": ws_infos
    }
